add_action( 'woocommerce_init', 'perfectpixel_block_checkout_privacy_checkbox' );

function perfectpixel_block_checkout_privacy_checkbox() {
	if ( ! function_exists( 'woocommerce_register_additional_checkout_field' ) ) {
		return; // WooCommerce older than 8.9.
	}
	woocommerce_register_additional_checkout_field(
		array(
			'id'       => 'perfectpixel/privacy-policy',
			'label'    => '{{privacy_label}}',
			'location' => 'order',
			'type'     => 'checkbox',
			'required' => true,
		)
	);
}
